/**
 * Every TypeScript snippet the VS Code extension offers -- one per build*()
 * function (BUILDER_METADATA, generated by scripts/extract-metadata.ts) and
 * one per caddy-security template -- must type-check against the real
 * library once accepted with its defaults. 0.2.0's generator emitted
 * unquoted strings (`path: /etc/caddy/config.json`), `servers: ""` for an
 * array of objects, and empty `({})` calls for builders with required
 * options.
 */
import { describe, test, expect } from "vitest";
import ts from "typescript";
import { join } from "path";
import { BUILDER_METADATA } from "../generated/extension-assets.js";
import { SECURITY_TEMPLATES } from "../plugins/caddy-security/index.js";
import { expandSnippet } from "./helpers/snippet-expand.js";

const ROOT = join(__dirname, "../..");
const SNIPPET_DIR = join(ROOT, "src/__snippet_check__");

interface Case {
  id: string;
  body: string[];
}

const cases: Case[] = [
  ...Object.values(BUILDER_METADATA).map((b) => ({
    id: `builder ${b.name} (${b.snippet.prefix})`,
    body: b.snippet.body,
  })),
  ...SECURITY_TEMPLATES.map((t) => ({ id: `template ${t.id}`, body: t.snippet })),
];

function typeCheck(all: Case[]): Map<string, string[]> {
  const files = new Map<string, string>();
  all.forEach((c, i) => {
    const code = expandSnippet(c.body);
    const used = [...new Set(code.match(/\bbuild[A-Z]\w*/g) ?? [])];
    files.set(
      join(SNIPPET_DIR, `snippet-${i}.ts`),
      // Templates are whole statement sequences; builder snippets are one call expression.
      `import { ${used.join(", ")} } from "../index.js";\n` +
        (/^\s*(\/\/|const |let )/.test(code)
          ? `${code}\nexport {};\n`
          : `export const value = ${code};\n`)
    );
  });

  const config = ts.readConfigFile(join(ROOT, "tsconfig.json"), (f) => ts.sys.readFile(f));
  const options = ts.parseJsonConfigFileContent(config.config, ts.sys, ROOT).options;
  const host = ts.createCompilerHost({ ...options, noEmit: true });
  const readFile = host.readFile.bind(host);
  const fileExists = host.fileExists.bind(host);
  const getSourceFile = host.getSourceFile.bind(host);
  host.readFile = (f) => files.get(f) ?? readFile(f);
  host.fileExists = (f) => files.has(f) || fileExists(f);
  host.getSourceFile = (f, lang, onError, create) => {
    const text = files.get(f);
    return text !== undefined
      ? ts.createSourceFile(f, text, lang, true)
      : getSourceFile(f, lang, onError, create);
  };

  // A template legitimately ends on an unused `const config = ...`.
  const checkOptions = { ...options, noEmit: true, noUnusedLocals: false };
  const program = ts.createProgram([...files.keys()], checkOptions, host);
  const result = new Map<string, string[]>();
  all.forEach((c, i) => {
    const sf = program.getSourceFile(join(SNIPPET_DIR, `snippet-${i}.ts`))!;
    const diags = [...program.getSyntacticDiagnostics(sf), ...program.getSemanticDiagnostics(sf)];
    result.set(
      c.id,
      diags.map((d) => ts.flattenDiagnosticMessageText(d.messageText, "\n"))
    );
  });
  return result;
}

describe("TypeScript builder/template snippets", () => {
  const results = typeCheck(cases);

  test("there is a snippet for every builder", () => {
    expect(Object.keys(BUILDER_METADATA).length).toBeGreaterThan(30);
  });

  test.each(cases.map((c) => [c.id, c] as const))("%s type-checks", (id, c) => {
    expect(results.get(id), expandSnippet(c.body)).toEqual([]);
  });

  test.each(Object.values(BUILDER_METADATA).map((b) => [b.name, b] as const))(
    "%s snippet ends at $0 after the call",
    (_, b) => {
      expect(b.snippet.body.join("\n")).toMatch(/\)\$0$/);
    }
  );
}, 60_000);
